nextflow_process {

    name "Test Process COPTR_ESTIMATE"
    script "../main.nf"
    process "COPTR_ESTIMATE"

    tag "modules"
    tag "modules_nfcore"
    tag "coptr"
    tag "coptr/extract"
    tag "coptr/estimate"

    setup {
        run("COPTR_EXTRACT") {
            script "../../extract/main.nf"
            process {
                """
                input[0] = [
                    [id:'test_0'],
                    [ file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true)
                    ]
                ]
                """
            }
        }
    }

    test("coptr estimate from coverage maps file") {

        when {
            process {
                """
                input[0] = COPTR_EXTRACT.out.coverage
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match()
                }
            )
        }

    }

    test("coptr estimate from coverage maps file - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = COPTR_EXTRACT.out.coverage
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match()
                }
            )
        }

    }


}

